use super::*;

// Independent hand-authored wire bytes; never generated by the encoder.
const PLAYER: &[u8] = &[
    1, // random dungeon count
    0x44, 0x33, 0x22, 0xa1, 0xfe, // entry, raw done
    1, 0, 0, 0, 2, 0, 0, 0, // money, XP
    3, 0, 0, 0, 4, 0, 0, 0, // reserved words retained
    1, // item count
    0x88, 0x77, 0x66, 0x55, 9, 0, 0, 0, 10, 0, 0, 0, 1, 0, 0, 0, // lock count
    0xdd, 0xcc, 0xbb, 0xee, 0xff, 0xff, 0xff, 0xff,
];
const PARTY: &[u8] = &[
    2, // member count
    8, 7, 6, 5, 4, 3, 2, 1, // GUID
    1, 0, 0, 0, // lock count
    0x44, 0x33, 0x22, 0xa1, 7, 0, 0, 0, 0xff, 0xee, 0xdd, 0xcc, 0xbb, 0xaa, 0x99, 0x88, 0, 0, 0,
    0, // explicit empty locks for second member
];

#[test]
fn player_preview_retains_raw_values_and_separate_locks() {
    assert_eq!(
        decode(SMSG_LFG_PLAYER_INFO, PLAYER).unwrap(),
        Packet::PlayerInfo(PlayerInfo {
            rewards: vec![RandomDungeonReward {
                entry: 0xa1223344,
                done: 0xfe,
                money: 1,
                xp: 2,
                reserved: [3, 4],
                items: vec![RewardItem {
                    item: 0x55667788,
                    display: 9,
                    count: 10
                }],
            }],
            locks: vec![DungeonLock {
                entry: 0xeebbccdd,
                reason: u32::MAX
            }],
        })
    );
}
#[test]
fn party_retains_order_full_guids_and_empty_member_reply() {
    assert_eq!(
        decode(SMSG_LFG_PARTY_INFO, PARTY).unwrap(),
        Packet::PartyInfo(vec![
            PartyMemberLocks {
                guid: 0x0102030405060708,
                locks: vec![DungeonLock {
                    entry: 0xa1223344,
                    reason: 7
                }]
            },
            PartyMemberLocks {
                guid: 0x8899aabbccddeeff,
                locks: vec![]
            },
        ])
    );
}
#[test]
fn empty_replies_are_valid_snapshots_not_absence() {
    assert_eq!(
        decode(SMSG_LFG_PLAYER_INFO, &[0, 0, 0, 0, 0]).unwrap(),
        Packet::PlayerInfo(PlayerInfo {
            rewards: vec![],
            locks: vec![]
        })
    );
    assert_eq!(
        decode(SMSG_LFG_PARTY_INFO, &[0]).unwrap(),
        Packet::PartyInfo(vec![])
    );
}
#[test]
fn every_truncation_and_trailing_byte_is_rejected() {
    for (opcode, body) in [(SMSG_LFG_PLAYER_INFO, PLAYER), (SMSG_LFG_PARTY_INFO, PARTY)] {
        for end in 0..body.len() {
            assert!(
                decode(opcode, &body[..end]).is_err(),
                "{opcode:x} prefix {end}"
            );
        }
        let mut extra = body.to_vec();
        extra.push(0);
        assert!(decode(opcode, &extra).is_err());
    }
}
#[test]
fn malicious_counts_fail_before_large_allocations() {
    for body in [
        &[0, 255, 255, 255, 255][..],
        &[255][..],
        &[1, 0, 0, 0, 0][..],
    ] {
        assert!(decode(SMSG_LFG_PLAYER_INFO, body).is_err());
    }
    assert!(decode(SMSG_LFG_PARTY_INFO, &[255]).is_err());
    let mut body = PARTY.to_vec();
    body[9..13].copy_from_slice(&u32::MAX.to_le_bytes());
    assert!(decode(SMSG_LFG_PARTY_INFO, &body).is_err());
    let mut body = PLAYER.to_vec();
    body[22] = 255; // item count
    assert!(decode(SMSG_LFG_PLAYER_INFO, &body).is_err());
}
#[test]
fn request_commands_have_exact_native_opcodes_and_empty_bodies() {
    for (command, opcode) in [
        (Command::RequestPlayerLockInfo, 0x036e),
        (Command::RequestPartyLockInfo, 0x0371),
    ] {
        assert_eq!(command.opcode(), opcode);
        assert!(command.encode().is_empty());
    }
    assert!(handles(0x036f));
    assert!(handles(0x0372));
    assert!(!handles(0x036e));
    assert!(decode(0xffff, &[]).is_err());
}

#[test]
fn adapter_delivers_one_lossless_reply_or_none_on_invalid_body() {
    use crate::{
        wrath_events::{WrathDispatch, WrathEventAdapter},
        SessionEvent,
    };
    let mut adapter = WrathEventAdapter::new();
    for (opcode, body) in [
        (SMSG_LFG_PLAYER_INFO, PLAYER),
        (SMSG_LFG_PARTY_INFO, PARTY),
        (SMSG_LFG_PLAYER_INFO, &[0, 0, 0, 0, 0][..]),
        (SMSG_LFG_PARTY_INFO, &[0][..]),
    ] {
        let WrathDispatch::Handled { session_events, .. } =
            adapter.dispatch(opcode, body, 0).unwrap()
        else {
            panic!()
        };
        assert!(
            matches!(&session_events[..], [SessionEvent::WrathLfg { packet }] if *packet == decode(opcode, body).unwrap())
        );
        for end in 0..body.len() {
            assert!(matches!(
                adapter.dispatch(opcode, &body[..end], 0).unwrap(),
                WrathDispatch::Unhandled { .. }
            ));
        }
        let mut trailing = body.to_vec();
        trailing.push(0);
        assert!(matches!(
            adapter.dispatch(opcode, &trailing, 0).unwrap(),
            WrathDispatch::Unhandled { .. }
        ));
    }
}

#[test]
fn queue_adapter_preserves_native_packets_and_optional_join_block() {
    use crate::{
        wrath_events::{WrathDispatch, WrathEventAdapter},
        SessionEvent,
    };
    // Independent minimal wire bodies, including nonboolean ready and signed wait sentinels.
    let cases: &[(u16, &[u8])] = &[
        (0x367, &[8, 0]),
        (0x368, &[9, 0]),
        (
            0x2bb,
            &[8, 7, 6, 5, 4, 3, 2, 1, 0xfe, 0xff, 0xff, 0xff, 0xff],
        ),
        (0x363, &[9, 0, 0, 0, 0xfe, 0, 0]),
        (0x364, &[6, 0, 0, 0, 7, 0, 0, 0]),
        (0x364, &[6, 0, 0, 0, 7, 0, 0, 0, 0]),
        (
            0x365,
            &[
                4, 3, 2, 0xa1, 255, 255, 255, 255, 0, 0, 0, 0, 0, 0, 0, 128, 255, 255, 255, 127, 5,
                0, 0, 0, 1, 2, 3, 255, 255, 255, 255,
            ],
        ),
    ];
    let mut adapter = WrathEventAdapter::new();
    for &(opcode, body) in cases {
        let WrathDispatch::Handled { session_events, .. } =
            adapter.dispatch(opcode, body, 0).unwrap()
        else {
            panic!()
        };
        assert!(
            matches!(&session_events[..], [SessionEvent::WrathLfg { packet: Packet::Queue(packet) }] if *packet == queue::decode(opcode, body).unwrap())
        );
        let mut trailing = body.to_vec();
        trailing.push(255);
        assert!(matches!(
            adapter.dispatch(opcode, &trailing, 0).unwrap(),
            WrathDispatch::Unhandled { .. }
        ));
        assert!(matches!(
            adapter
                .dispatch(opcode, &body[..body.len() - 2], 0)
                .unwrap(),
            WrathDispatch::Unhandled { .. }
        ));
    }
}
